import java.io.*;
import java.util.*;

public class Files {
    static void process(String path) {               // sum numbers in a file
        try (Scanner sc = new Scanner(new FileReader(path))) {
            int sum = 0;
            while (sc.hasNextInt()) sum += sc.nextInt();
            System.out.println("Sum = " + sum);
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + e.getMessage());
        }
    }
    static void save(String path, ArrayList<String> lines) throws IOException {
        try (PrintWriter out = new PrintWriter(path)) {   // overwrites
            for (String l : lines) out.println(l);
        }                                                 // auto-closed
    }
    static void logLine(String text) throws IOException { // appends
        try (PrintWriter out = new PrintWriter(new FileWriter("log.txt", true))) {
            out.println(text);
        }
    }
    public static void main(String[] args) throws IOException {
        process("numbers.txt");
        save("names.txt", new ArrayList<>(List.of("Amantle", "Kabo")));
    }
}

